const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const header=document.querySelector('.topbar');let headerFrame=0;const syncHeader=()=>{header.classList.toggle('is-compact',window.scrollY>36);headerFrame=0};window.addEventListener('scroll',()=>{if(!headerFrame)headerFrame=requestAnimationFrame(syncHeader)},{passive:true});syncHeader();
const logoLink=document.querySelector('.topbar .brand-motion'),reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');let logoTimer;function playLogo(){if(reduceMotion.matches)return;logoLink.classList.remove('is-replaying');void logoLink.offsetWidth;logoLink.classList.add('is-replaying');clearTimeout(logoTimer);logoTimer=setTimeout(()=>logoLink.classList.remove('is-replaying'),1200)}logoLink.addEventListener('click',playLogo);playLogo();
const form=document.querySelector('#caseForm'),panels=[...document.querySelectorAll('.panel')],prev=document.querySelector('#prev'),next=document.querySelector('#next'),finish=document.querySelector('#finish'),error=document.querySelector('#formError'),progress=document.querySelector('#progress'),progressText=document.querySelector('#progressText'),result=document.querySelector('#result');let step=1;
function show(){panels.forEach(p=>p.classList.toggle('active',Number(p.dataset.step)===step));progress.value=step;progressText.textContent=`Paso ${step} de 4`;prev.hidden=step===1;next.hidden=step===4;finish.hidden=step!==4;error.textContent=''}function valid(){const p=panels[step-1],checked=p.querySelector('input:checked');if(!checked){error.textContent='Selecciona una opción para continuar.';p.querySelector('input').focus();return false}return true}
next.addEventListener('click',()=>{if(valid()){step++;show()}});prev.addEventListener('click',()=>{step--;show()});document.querySelectorAll('.problem').forEach(b=>b.addEventListener('click',()=>{document.querySelector(`input[name="problem"][value="${b.dataset.problem}"]`).checked=true;document.querySelector('#orientador').scrollIntoView()}));
const labels={medicamento:'entrega de un medicamento',procedimiento:'autorización de un procedimiento',especialista:'asignación de cita o especialista',continuidad:'continuidad de un tratamiento',negacion:'negación de un servicio'};function restart(){result.hidden=true;form.hidden=false;step=1;show();form.scrollIntoView()}
form.addEventListener('submit',e=>{e.preventDefault();if(!valid())return;const d=new FormData(form),urgent=d.get('urgent')==='yes';form.hidden=true;result.hidden=false;if(urgent){result.innerHTML='<p class="eyebrow">Atención prioritaria</p><h3>No esperes una orientación digital</h3><div class="urgent"><b>Si existe riesgo inmediato para la vida o la integridad, acude a un servicio de urgencias o utiliza los canales oficiales de emergencia.</b></div><p>Salvación M no presta atención médica ni realiza triage clínico.</p><button class="button ghost" id="restart">Volver a empezar</button>';document.querySelector('#restart').onclick=restart;return}const a=Object.fromEntries(d.entries());result.innerHTML=`<p class="eyebrow">Consulta inicial gratuita</p><h3>Solicita la revisión sobre ${labels[a.problem]}</h3><p>La fecha elegida es una solicitud y quedará confirmada cuando Salvación M la acepte.</p><form id="leadForm" class="lead-form"><label>Nombre completo<input name="name" autocomplete="name" required maxlength="120"></label><label>WhatsApp<input name="phone" inputmode="tel" autocomplete="tel" required pattern="[0-9 +()-]{7,20}" maxlength="20"></label><label>Correo electrónico<input name="email" type="email" autocomplete="email" required maxlength="160"></label><label>Fecha y hora preferida (hora de Colombia)<input name="preferred_at" type="datetime-local" required></label><label>Resumen breve, sin historia clínica<textarea name="summary" maxlength="700"></textarea></label><label class="consent"><input name="consent" type="checkbox" required><span>Autorizo el tratamiento de mis datos para gestionar esta consulta conforme a la <a href="#privacidad">política de privacidad</a>.</span></label><div id="leadStatus" class="form-status" hidden></div><div><button class="button primary">Enviar solicitud</button> <button type="button" class="button ghost" id="restart">Revisar respuestas</button></div></form>`;document.querySelector('#restart').onclick=restart;const lf=document.querySelector('#leadForm');lf.onsubmit=async ev=>{ev.preventDefault();const status=document.querySelector('#leadStatus'),button=lf.querySelector('button[type="submit"]');status.hidden=false;status.textContent='Enviando…';button.disabled=true;try{const c=Object.fromEntries(new FormData(lf).entries()),r=await fetch('/api/consultations',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...a,...c,consent:true})}),p=await r.json();if(!r.ok)throw new Error(p.error||'No fue posible guardar la solicitud.');lf.innerHTML=`<p class="eyebrow">Solicitud recibida</p><h3>Gracias, ${p.name}.</h3><p class="reference">Referencia ${p.reference}</p><p>Tu consulta y fecha preferida quedaron registradas.</p><a class="button primary" target="_blank" rel="noopener" href="${p.whatsapp_url}">Continuar por WhatsApp</a>`}catch(x){status.className='form-status error';status.textContent=x.message;button.disabled=false}}});
